-- GENERATED by osquery/tools/build.py. Do not edit.
-- Source of truth is osquery/queries/*.sql; edit there and rebuild.
-- Columns, in order: kind, id, ver, loc, extra, perms
--
-- PLATFORM: windows. Run this only on windows. The tables named here do not all
-- exist elsewhere, and osqueryi given a missing table returns "[\n\n]" -- valid,
-- empty, entirely plausible JSON -- and exits 1. Every other artifact in dist/ is for a
-- different platform and is NOT a superset of this one. bin/discover picks by `uname -s`.

-- from browser-windows.sql
SELECT 'ext' AS kind, identifier AS id, version AS ver, profile_path AS loc,
       browser_type
         || CASE WHEN referenced = 0 THEN ',unreferenced'
                 WHEN from_webstore != 'true'
                   THEN ',sideloaded:' || IFNULL(manifest_hash, '')
                 ELSE '' END
         AS extra,
       permissions
         || CASE WHEN manifest_json LIKE '%<all_urls>%' THEN ',<all_urls>' ELSE '' END
         AS perms
  FROM (SELECT uid FROM users) u
       CROSS JOIN chrome_extensions USING (uid)

UNION ALL

-- from filesystem-windows.sql
SELECT 'file' AS kind, f.path AS id, '' AS ver, f.path AS loc, '' AS extra, '' AS perms
  FROM users u CROSS JOIN file f ON f.path LIKE u.directory || '\.local\bin\%'
 WHERE u.directory LIKE '_:\Users\%'
UNION ALL
SELECT 'file', f.path, '', f.path, '', ''
  FROM users u CROSS JOIN file f ON f.path LIKE u.directory || '\.%\'
 WHERE u.directory LIKE '_:\Users\%'
UNION ALL
-- PYTHON-PACKAGED AGENTS, through the tool directories pipx and uv make on Windows by default
-- (`pipx environment`, `uv tool dir`), each named for its package. bin/classify's tool-dir
-- match reads the name back (SPEC.md 6.4.6).
SELECT 'file', f.path, '', f.path, '', ''
  FROM users u CROSS JOIN file f ON f.path LIKE u.directory || '\AppData\Local\pipx\pipx\venvs\%\'
 WHERE u.directory LIKE '_:\Users\%'
UNION ALL
SELECT 'file', f.path, '', f.path, '', ''
  FROM users u CROSS JOIN file f ON f.path LIKE u.directory || '\AppData\Roaming\uv\tools\%\'
 WHERE u.directory LIKE '_:\Users\%'

UNION ALL

-- from native-messaging-windows.sql
SELECT 'nmh' AS kind, f.filename AS id, '' AS ver, f.path AS loc, '' AS extra, '' AS perms
  FROM registry r CROSS JOIN file f ON f.path = r.data
 WHERE r.key LIKE 'HKEY_USERS\%\Software\%\NativeMessagingHosts\%' AND r.name = '(Default)'
UNION ALL
SELECT 'nmh', f.filename, '', f.path, '', ''
  FROM registry r CROSS JOIN file f ON f.path = r.data
 WHERE r.key LIKE 'HKEY_USERS\%\Software\%\%\NativeMessagingHosts\%' AND r.name = '(Default)'
UNION ALL
SELECT 'nmh', f.filename, '', f.path, '', ''
  FROM registry r CROSS JOIN file f ON f.path = r.data
 WHERE r.key LIKE 'HKEY_LOCAL_MACHINE\SOFTWARE\%\NativeMessagingHosts\%' AND r.name = '(Default)'
UNION ALL
SELECT 'nmh', f.filename, '', f.path, '', ''
  FROM registry r CROSS JOIN file f ON f.path = r.data
 WHERE r.key LIKE 'HKEY_LOCAL_MACHINE\SOFTWARE\%\%\NativeMessagingHosts\%' AND r.name = '(Default)'
UNION ALL
SELECT 'nmh', f.filename, '', f.path, '', ''
  FROM registry r CROSS JOIN file f ON f.path = r.data
 WHERE r.key LIKE 'HKEY_LOCAL_MACHINE\SOFTWARE\WOW6432Node\%\%\NativeMessagingHosts\%'
   AND r.name = '(Default)'

UNION ALL

-- from packages-windows.sql
SELECT 'npm' AS kind, name AS id, version AS ver, path AS loc, '' AS extra, '' AS perms
  FROM npm_packages
  WHERE path NOT LIKE '%\node_modules\%\node_modules\%'

UNION ALL

-- from programs-windows.sql
SELECT 'msix' AS kind, package_family_name AS id, version AS ver, install_location AS loc,
       publisher AS extra, '' AS perms
  FROM programs
 WHERE package_family_name != ''

UNION ALL

-- from running-windows.sql
SELECT 'proc' AS kind,
       replace(regex_match(path || ' ' || cmdline,
                           'node_modules[\\/]((?:@[A-Za-z0-9][A-Za-z0-9._-]*[\\/])?[A-Za-z0-9][A-Za-z0-9._-]*)', 1),
               '\', '/') AS id,
       '' AS ver, path AS loc, '' AS extra, '' AS perms
  FROM processes
  WHERE (path LIKE '%\node_modules\%'
         OR ((path LIKE '%\node.exe' OR path LIKE '%\bun.exe' OR path LIKE '%\deno.exe')
             AND cmdline LIKE '%node_modules%'))
    AND regex_match(path || ' ' || cmdline,
                    'node_modules[\\/]((?:@[A-Za-z0-9][A-Za-z0-9._-]*[\\/])?[A-Za-z0-9][A-Za-z0-9._-]*)', 1) IS NOT NULL
  GROUP BY id, loc
UNION ALL
-- RUNNING FROM A HOME DIRECTORY, by executable path, as in running.sql.
SELECT 'proc', path, '', path, '', ''
  FROM processes
  WHERE path LIKE '_:\Users\%\%'
  GROUP BY path

UNION ALL

-- from runtime-windows.sql
SELECT 'scan' AS kind, 'containers' AS id, CAST(t.unix_time AS TEXT) AS ver,
       '\\.\pipe\docker_engine' AS loc,
       CASE WHEN dm.n + dd.n + dk.n > 0 THEN 'unreadable:docker'
            WHEN pm.n > 0 THEN 'unreadable:podman'
            WHEN rd.n > 0 THEN 'unreadable:rancher-desktop'
            ELSE 'absent' END AS extra,
       '' AS perms
  FROM time t,
       (SELECT COUNT(*) AS n FROM file WHERE path = 'C:\Windows\System32\dockerd.exe') dm,
       (SELECT COUNT(*) AS n FROM file WHERE path = 'C:\ProgramData\docker\') dd,
       (SELECT COUNT(*) AS n FROM file WHERE path = 'C:\Program Files\Docker\Docker\') dk,
       (SELECT COUNT(*) AS n FROM file
         WHERE path = 'C:\Program Files\RedHat\Podman\podman.exe') pm,
       (SELECT COUNT(*) AS n FROM users u
         CROSS JOIN file f ON f.path = u.directory || '\AppData\Local\Programs\Rancher Desktop\'
         WHERE u.directory LIKE '_:\Users\%') rd

UNION ALL

-- from uninstall-windows.sql
SELECT 'uninstall' AS kind, regex_match(n.key, '[^\\]+(?![\s\S])', 0) AS id,
       IFNULL(v.data, '') AS ver, n.key AS loc, n.data AS extra, '' AS perms
  FROM registry n
       LEFT JOIN registry v ON v.key = n.key AND v.name = 'DisplayVersion'
 WHERE n.key LIKE 'HKEY_LOCAL_MACHINE\SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall\%'
   AND n.name = 'DisplayName'
UNION ALL
SELECT 'uninstall', regex_match(n.key, '[^\\]+(?![\s\S])', 0), IFNULL(v.data, ''), n.key, n.data, ''
  FROM registry n
       LEFT JOIN registry v ON v.key = n.key AND v.name = 'DisplayVersion'
 WHERE n.key LIKE 'HKEY_LOCAL_MACHINE\SOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\Uninstall\%'
   AND n.name = 'DisplayName'
UNION ALL
SELECT 'uninstall', regex_match(n.key, '[^\\]+(?![\s\S])', 0), IFNULL(v.data, ''), n.key, n.data, ''
  FROM registry n
       LEFT JOIN registry v ON v.key = n.key AND v.name = 'DisplayVersion'
 WHERE n.key LIKE 'HKEY_USERS\%\Software\Microsoft\Windows\CurrentVersion\Uninstall\%'
   AND n.name = 'DisplayName'

UNION ALL

-- from vscode-windows.sql
SELECT 'vscodeext' AS kind, name AS id, version AS ver, path AS loc,
       vscode_edition AS extra, '' AS perms
  FROM (SELECT uid FROM users) u
       CROSS JOIN vscode_extensions USING (uid);
